INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('html_reference_navigation', e'<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <meta
            name="viewport"
            content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0"
    />
    <meta http-equiv="X-UA-Compatible" content="ie=edge" />
    <title>Document</title>
    <style>
        * {
            margin: 0 0 0 0;
            border: none;
            padding: 0 0 0 0;
            font-family: Arial, sans-serif;
            font-size: 16px;
            line-height: 1.7em;
            user-select: none;
            -moz-user-select: none;
            -webkit-user-select: none;
            -ms-user-select: none;
        }

        html, body {
            height: 100%;
            width: 100%;
            overflow-x: hidden;
        }

        #nav-list {
            display: grid;
            /*height: 100%;*/
            width: 100%;
            gap: 2px;
            padding: 5px;
            grid-template-columns: max-content auto;
        }
        .nav-info {
            font-weight: bold;
            margin-right: 1em;
        }
        .no-identifier {
            display:grid;
            width: 100%;
            height: 100%;
            place-content: center;
            font-weight: bold;
            text-align: center;
            background-color: #FABC02;
        }
        .no-identifier span {
            text-align: center;
            font-size: .6em;
        }
        .selected {
            background-color: #3F3F3D;
            color: white;
        }
    </style>
</head>
<body>
<div id="nav-list">

</div>
<script>
    **data**
    /* replace the next lines in FileMaker  with just **data** */
  //   var inputText = `Day five!
  //
  // Plan for today is to excavate two more deposit contexts associated with shelf A-012 . We are using lots this time around and none of my available contexts are very loty, so we’re going to get creative. `
  //   var regexs = [String.raw`\\b\\w*?-\\w*\\b`,String.raw`\\"\\s*(?<identifier>.*?)\\s*\\"`]
    /* replace the above lines in FileMaker  with just **data** */

    function installClickHandlers() {
        var items = document.querySelectorAll(".nav-info");
        items.forEach((item) => {
            item.addEventListener("click", function () {
                this.classList.add("selected");
                const identifier = this.getAttribute("data-identifier")
                console.log(identifier)
                FileMaker.PerformScript("**nav_function**", identifier)
            });
        });
    }

    function showIdentifiers(identifier_text) {
        // called by FileMaker: A list of identifiers with their record types and names
        // in the format identifier$$record_type$$record type name##

        identifier_text = identifier_text.trim()
        identifiers = identifier_text.split("##")
        const list = document.getElementById("nav-list")
        if (identifier_text.length > 0 && identifiers.length > 0) {
            identifiers.sort()
            identifiers.forEach((identifier_item) => {
                const identifier = identifier_item.split("$$")
                const div = document.createElement("div")
                div.textContent = identifier[0]
                div.classList.add("nav-info")
                div.setAttribute("data-identifier", identifier[1] + "::" + identifier[0])
                list.appendChild(div)
                const record_type_div = document.createElement("div")
                record_type_div.textContent = identifier[2]
                // record_type_div.classList.add("nav-info")
                list.appendChild(record_type_div)
            })
            installClickHandlers()
        } else {
            const div = document.createElement("div")
            div.innerHTML = "❔ No archaeological identifier identified in the text.<br> <span>(no pun intended)</span>"
            div.classList.add("no-identifier")
            list.replaceWith(div)
        }
    }

    function findIdentifiers() {
        let identifiers = []
        for (let pattern of regexs) {
            let reg = new RegExp(pattern,"g")
            let result

            // debugger;
            let c = 0 //dumb safety catch
            while (result = reg.exec(inputText)) {
                let identifier
                if (++c > 100) break;
                if (result[0] !== "") {
                    if (result.groups && Object.hasOwn(result.groups, "identifier")) {
                        identifier = result.groups.identifier
                    } else {
                        identifier = result[0]
                    }
                    if (identifier) {
                        if (!identifiers.find(element => element === identifier)) identifiers.push(identifier)
                    }
                } else break;
            }
        }
        return identifiers
    }

    identifiers = findIdentifiers()
    const list = document.getElementById("nav-list")
    if (identifiers.length > 0) {
        let fmIdentifiers = identifiers.join("$$")
        setTimeout(() => {
			FileMaker.PerformScript("checkIdentifiers", fmIdentifiers)
		}, 500);
        // showIdentifiers("LA-016$$locus$$context##AA-016$$locus$$context##SA$$unit$$unit##")
    } else {
        const div = document.createElement("div")
        div.innerHTML = "❔ No archaeological identifier could be identified in the text.<br> <span>(no pun intended)</span>"
        div.classList.add("no-identifier")
        list.replaceWith(div)
    }
</script>
</body>
</html>
', null, 'html', e'HTML for the navigation that finds references in texts and turns them into navigatable identifiers.
(replace **data** and **nav_function**)', null, 1, 'e09a2284-4241-df49-af90-c9686c3c6acf', '2023-05-02 19:39:15.000000', '2023-05-04 13:52:32.000000 +00:00', 'ADMIN', false, null, null, null, '2023-05-04 13:52:32.000000', null);
