INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('html_svg', e'<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta
      name="viewport"
      content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0"
    />
    <meta http-equiv="X-UA-Compatible" content="ie=edge" />
  </head>
  <style>
    svg {
      width: 100%;
      height: 100%;
    }
  </style>
  <body
    style="
      margin: 0px;
      padding: 0px;
      max-width: 100vw;
      max-height: 100vh;
      overflow: hidden;
    "
  >
    <div
      style="
        display: block;
        display: flex;
        justify-content: center;
        align-items: center;
        width: 95vw;
        height: 100vw;
        max-height: 100vh;
        padding: 0px;
      "
    >
    **svg**
    </div>
  </body>
</html>
', null, 'html', 'html template for showing an svg', null, 1, 'a0c5c426-9421-eb48-8356-538a91675af5', '2022-11-21 19:40:25.000000', '2022-11-21 19:41:37.000000 +00:00', 'ADMIN', false, null, null, null, '2022-11-21 19:41:37.000000', null);
INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('header_color', 'dark', null, 'visibility', 'use "dark" if the header background in start is rather darkish and you want the labels to stick out more', null, 1, '9bb0e75d-b47f-6a4f-8fd3-7d402a52d33b', '2022-05-26 12:41:19.000000', '2022-05-26 12:42:11.000000 +00:00', 'admin', false, null, null, null, '2022-05-26 12:42:11.000000', null);
INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('identification_method_free_input_locus', '66818ed1-4c0f-c542-bd64-3db9480b145d', null, 'identification', 'the identification method when creating a LOCUS if the registrar or admin activates the temporary free input override. If the temporary free override is not activated this has NO effect. ', 'num', 1, 'e5d47038-53ab-1049-b127-9defb2b477b3', '2022-12-07 17:19:47.000000', '2022-12-12 16:57:17.000000 +00:00', 'admin', false, null, null, null, '2022-12-12 16:57:17.000000', null);
INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('identification_method_free_input_cm', 'ad1fc384-371e-e146-9eda-d3906860e18c', null, 'identification', 'the identification method when creating a collected material if the registrar or admin activates the temporary free input override. If the temporary free override is not activated this has NO effect. There might also be a more specific free input identification method configured for the cm type which would have precendent. ', 'num', 1, 'c7d4aa2e-9b05-3644-bd94-858916da49c5', '2022-12-07 17:20:55.000000', '2022-12-12 16:57:17.000000 +00:00', 'admin', false, null, null, null, '2022-12-12 16:57:17.000000', null);
