INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('identification_method_coordinate', '5db6a70a-f54e-4c66-8c6c-1cb5b67fa5fd', null, 'identification', 'this identification method will determine the name of a new coordinate in the survey module', 'num', 1, '0ab72795-ee0e-5747-aaed-ab5f274434ad', '2023-03-20 20:19:25.000000', '2023-03-24 16:18:56.000000 +00:00', 'admin', false, null, null, null, '2023-03-24 16:18:56.000000', null);
INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('skip_check_fork_time_earlier', 'nope', null, 'general', '"nope" is recommended here. Only set to "yup" if you are sure you want to deactivate this safety check. It makes sure that the database you are working in has not been set by a server that is on a future date and time.', null, 1, 'a22138d5-4947-1843-a9e9-3df29aaed6ab', '2023-04-25 12:15:24.000000', '2023-06-01 16:40:40.000000 +00:00', 'ADMIN', false, null, null, null, '2023-06-01 16:40:40.000000', null);
