', null, 'html', null, null, 1, 'e6ef588d-bfd5-e74f-bb55-7ff1dc8a5d83', '2023-06-18 12:48:30.000000', '2025-01-07 22:53:13.000000 +00:00', '', false, null, null, 10794809, '2025-01-08 00:53:13.000000', 63871912393046);
INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('find_identifier_css', e'a {
    text-decoration: none;
color: black;
  }
 .id-table {
     display: flex;
     flex-flow: column;
     width: 100%;
     user-select: none;
     -moz-user-select: none;
     -webkit-user-select: none;
 }
 .id-table-header {
     background: #dddddd;
 }

 .id-table-row {
     display: flex;
     text-align: left;
     /*justify-content: space-between;*/
     flex-flow: row;
     width: 100%;
     margin-bottom: .5em;
     padding: .5em 0 .5em 0;
 }
        .id-table-row div {
            cursor: pointer;
            word-wrap: break-word;
            margin-left: 1em;
        }

        .id-table-row div:nth-child(1) {
            min-width: 20vw;
            width: 20vw;
        }

        .id-table-row div:nth-child(2) {
            min-width: 20vw;
            width: 20vw;
        }

        .id-table-row div:nth-child(3) {
            width: 20vw;
            min-width: 20vw;
        }

        .id-table-row div:nth-child(4) {
            width: 25vw;
            min-width: 25vw;
        }

.id-table-data-row:hover {
     background: #0f9d58;
 }
.too-many-rows {
background-color: #BF2C2C;
color: white;
width: 100%;
padding: .5em;
}

