INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('html_raspi_e_ink_part1', e'<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta
      name="viewport"
      content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0"
    />
    <meta http-equiv="X-UA-Compatible" content="ie=edge" />
    <title>Document</title>

    <style>
      :root {
        --qr-code-size: 95vh;
      }
      /* This is just the spinner */
      .lds-ellipsis {
        margin-top: 0.5em;
        display: inline-block;
        position: relative;
        width: 80px;
        height: 20px;
      }
      .lds-ellipsis div {
        position: absolute;
        top: 5px;
        width: 15px;
        height: 15px;
        border-radius: 50%;
        background: #fff;
        animation-timing-function: cubic-bezier(0, 1, 1, 0);
      }
      .lds-ellipsis div:nth-child(1) {
        left: 8px;
        animation: lds-ellipsis1 0.6s infinite;
      }
      .lds-ellipsis div:nth-child(2) {
        left: 8px;
        animation: lds-ellipsis2 0.6s infinite;
      }
      .lds-ellipsis div:nth-child(3) {
        left: 32px;
        animation: lds-ellipsis2 0.6s infinite;
      }
      .lds-ellipsis div:nth-child(4) {
        left: 56px;
        animation: lds-ellipsis3 0.6s infinite;
      }
      @keyframes lds-ellipsis1 {
        0% {
          transform: scale(0);
        }
        100% {
          transform: scale(1);
        }
      }
      @keyframes lds-ellipsis3 {
        0% {
          transform: scale(1);
        }
        100% {
          transform: scale(0);
        }
      }
      @keyframes lds-ellipsis2 {
        0% {
          transform: translate(0, 0);
        }
        100% {
          transform: translate(24px, 0);
        }
      }
    </style>
    <style>
      .qr-center-style {
        /* display: grid;
        place-content: center;
        height: 95vh */
        margin-top: 2em;
        margin-left: 2em;
      }
      #qrcode img {
        height: var(--qr-code-size);
      }
      .deactivated {
        opacity: 10%;
      }
      #menu {
        position: fixed;
        left: 1em;
        top: 1em;
        width: 100%;
        height: 100%;
        display: none;
        flex-direction: column;
      }
      .menuitem {
        display: flex;
        width: 100%;
        max-width: 500px;
        flex-direction: row;
        font-family: monospace;
        font-size: 22px;
        padding: 1em 1em 2em 1em;
        user-select: none;
      }
      .menuitem svg {
        width: auto;
        height: 64px;
        margin-right: 1em;
      }
      .clickable:hover {
        /* background: rgba(255, 255, 255, 0.7); */
        filter: invert(48%) sepia(69%) saturate(476%) hue-rotate(46deg)
          brightness(98%) contrast(119%);
        border-radius: 25px;
        font-weight: bold;
      }
      .clickable:active {
        filter: invert(48%) sepia(19%) saturate(2476%) hue-rotate(296deg)
          brightness(78%) contrast(119%);
        border-radius: 25px;
        font-weight: bold;
      }

      .align-center {
        align-self: center;
      }
      label {
        font-size: 14px;
      }
      select,
      input {
        padding: 0.2em;
        font-size: 18px;
      }
      .input-section {
        padding-top: 1em;
        display: flex;
        flex-direction: column;
      }
      .some-button {
        border: 2px solid #bc1142;
        border-radius: 10px;
        padding: 2px 5px;
        font-size: 14px;
        font-weight: bold;
        width: 8em;
        margin-top: 5px;
        background-color: #75a928;
        text-align: center;
      }
      .some-button:active {
        background-color: #9acd3d;
      }
      .some-button:hover {
        border-width: 3px;
        padding: 1px 4px;
      }
      #options {
        display: none;
      }
      #menu-raspi {
        position: relative;
      }
      #message-overlay {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 0px;
        left: 0px;
        width: 100%;
        height: 100%;
        background-color: #75a928;
        align-items: center;
        justify-content: center;
        z-index: 1;
        padding: 0.5em;
      }
      #message-overlay.message-error {
        background-color: #bc1142;
        color: white;
      }
      #spinner {
        display: none;
      }
      #message-ok {
        display: none;
      }
      #message-ok.some-button {
        margin-top: 2em;
      }
    </style>
  </head>

  <body>
    <div id="qrcode"></div>
    <div id="menu">
      <div id="menu-close" class="menuitem" data-action="close">
        <svg
          class="clickable"
          xmlns="http://www.w3.org/2000/svg"
          viewBox="5 5 54 54"
        >
          <path
            d="M32 10c-12.15 0-22 9.85-22 22s9.85 22 22 22 22-9.85 22-22-9.85-22-22-22zm0 4c9.941 0 18 8.059 18 18s-8.059 18-18 18-18-8.059-18-18 8.059-18 18-18zm-6.363 9.637a2 2 0 0 0-1.414 3.414L29.172 32l-4.95 4.95a2 2 0 1 0 2.829 2.827L32 34.828l4.95 4.95a2 2 0 1 0 2.827-2.829L34.828 32l4.95-4.95a2 2 0 1 0-2.829-2.827L32 29.172l-4.95-4.95a1.994 1.994 0 0 0-1.413-.585z"
          />
        </svg>
        <div class="align-center clickable">close qr code</div>
      </div>
      <div id="menu-raspi" class="menuitem">
        <div id="message-overlay">
          <div id="message">on it!</div>
          <div id="message-ok" class="some-button">got it.</div>
          <div id="spinner">
            <div class="lds-ellipsis">
              <div></div>
              <div></div>
              <div></div>
              <div></div>
            </div>
          </div>
        </div>
        <svg
          class="clickable"
