    <script>
      function closeQRCode() {
        if (!developmentMode) {
          FileMaker.PerformScript("closeQRCodePopup", "");
        } else {
          alert("close!");
        }
      }

      function formToVariables() {
        let el = document.getElementById("lan-address");
        lanAddress = el.value;
        el = document.getElementById("display-type");
        displayType = el.value;
        el = document.getElementById("font-size");
        fontSize = el.value;
        el = document.getElementById("scale-type");
        scaleType = el.value;
      }
      function fetchResult(msg, result = false) {
        let elSpinner = document.getElementById("spinner");
        elSpinner.style.display = "none";
        let elMessage = document.getElementById("message");
        elMessage.innerHTML = msg;
        let elMessageOk = document.getElementById("message-ok");
        elMessageOk.style.display = "block";
        if (!result) {
          let elMessageOverlay = document.getElementById("message-overlay");
          elMessageOverlay.classList.add("message-error");
        }
      }
      function sendQRCodeData() {
        let elPleaseWait = document.getElementById("message-overlay");
        elPleaseWait.style.display = "flex";
        if (elPleaseWait.classList.contains("message-error")) {
          elPleaseWait.classList.remove("message-error");
        }
        let elSpinner = document.getElementById("spinner");
        elSpinner.style.display = "flex";
        let elMessageOk = document.getElementById("message-ok");
        elMessageOk.style.display = "none";
        let elMessage = document.getElementById("message");
        elMessage.innerHTML = "On it!";

        console.log("sending QR Code data to Raspi...");
        formToVariables();
        url = `http://${lanAddress}`;
        try {
          fetch(url + "/version")
            .then((response) => {
              if (response.ok) {
                return response.json();
              } else {
                fetchResult(
                  `The RasPi reacted with an error ${response.status}: ${response.statusText}. Check if all options are correct.`
                );
              }
            })
            .then((data) => {
              if (data["app"] !== "Kiosk E-Ink Display Server") {
                fetchResult(
                  "The responding server is not a Kiosk E-Ink Display Server."
                );
              } else {
                let formData = new FormData();
                formData.append("data", qrCodeData);
                formData.append("label", qrCodeLabel);
                formData.append("lan-address", lanAddress);
                formData.append("display-type", displayType);
                formData.append("font-size", fontSize);
                formData.append("scale-type", scaleType);

                return fetch(url + "/show", {
                  body: formData,
                  method: "post",
                });
              }
            })
            .then((response) => {
              if (response.ok) {
                return response.json();
              } else {
                fetchResult(
                  `The RasPi reacted with an error ${response.status}: ${response.statusText}. Check if all options are correct.`
                );
              }
            })
            .then((data) => {
              if (!data["result"]) {
                fetchResult(
                  `The RasPi was not able to display the qr code correctly. Check if all options are correct.`
                );
              } else {
                fetchResult("The QR-Code should be on the display!", true);
                let saveData = `lanAddress=${lanAddress}\\ndisplayType=${displayType}\\nfontSize=${fontSize}\\nscaleType=${scaleType}`;
                closeQRCode();

              }
            })
            .catch((error) => {
              fetchResult(
                "A network error occured. Presumably network address or port are not in order or there is no Raspi listening."
              );
            });
        } catch {
          console.log("catch reached.");
        }
      }

      function menuItemClicked(event) {
        let parent = event.target.parentElement;
        if (!parent.classList.contains("menuitem")) {
          parent = parent.parentElement;
        }
        if (parent.classList.contains("menuitem")) {
          if (parent.id === "menu-raspi") {
            sendQRCodeData();
          } else {
            if (parent.id === "menu-close") {
              closeQRCode()
            }
          }
        }
      }

      function setDefaults() {
        let el = document.getElementById("lan-address");
        el.value = lanAddress;
        el = document.getElementById("display-type");
        el.value = displayType;
        el = document.getElementById("font-size");
        el.value = fontSize;
        el = document.getElementById("scale-type");
        el.value = scaleType;
      }

      /*********************************************************************************
       *
       * initialization
       *
       *********************************************************************************/
      let lanAddress;
      let displayType;
      let fontSize;
      let scaleType;
      let developmentMode = false;
      let qrCodeData;
      let qrCodeLabel;
      let qrCodeSize;

      initValues();

      if (lanAddress === "**lanAddress**") {
        developmentMode = true;
        lanAddress = "192.168.178.35:5000";
        displayType = "1.54";
        fontSize = "auto";
        scaleType = "auto";
        qrCodeData =
          "asdföwoiuerouwre32482743§Q$%WESRGISADF§RI|ASfdkjlkaflkwor3ui2ur3oakdöhfkjalfsaflkasj";
        qrCodeLabel = "FH-001-2\\n24VIII22";
        qrCodeScale = "auto"
      }

      if (qrCodeScale === "auto") {
        qrCodeSize = 512
      } else {
        qrCodeSize = parseInt(qrCodeScale)
      }

      new QRCode("qrcode", {
        text: qrCodeData,
        width: qrCodeSize,
        height: qrCodeSize,
      });

      let qrcode = document.getElementById("qrcode");
      let menu = document.getElementById("menu");
      let options = document.getElementById("options");
      let optionsButton = document.getElementById("options-button");
      let r = document.querySelector(\':root\');
      if (qrCodeScale !== "auto") {
        r.style.setProperty(\'--qr-code-size\', qrCodeScale);
        // qrcode.classList.add("qr-center-style");
      }
      qrcode.addEventListener("click", () => {
        if (qrCodeSize >= 400 && lanAddress !== "-") {
          if (!qrcode.classList.contains("deactivated")) {
            qrcode.classList.add("deactivated");
            menu.style.display = "flex";
          }
        } else {
          closeQRCode()
        }
      });
      menu.addEventListener("click", (event) => {
        if (event.srcElement.id === "menu") {
          qrcode.classList.remove("deactivated");
          menu.style.display = "none";
        }
      });
      optionsButton.addEventListener("click", () => {
        options.style.display = "block";
        optionsButton.style.display = "none";
      });

      let elMessageOk = document.getElementById("message-ok");
      elMessageOk.addEventListener("click", () => {
        let elMessage = document.getElementById("message-overlay");
        elMessage.style.display = "none";
      });
      let clickables = document.getElementsByClassName("clickable");
      for (e of clickables) {
        e.addEventListener("click", menuItemClicked);
      }
