INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('reference_navigation_regexs', e'[\\"|“]\\s*(?<identifier>.*?)\\s*[\\"|”]
[\\\'|‘]\\s*(?<identifier>.*?)\\s*[\\\'|’]
\\^\\s*(?<identifier>.*?)\\s
\\(\\s*(?<identifier>.*?)\\s*\\)
\\[\\s*(?<identifier>.*?)\\s*\\]
\\<\\s*(?<identifier>.*?)\\s*\\>
(\\w*?-[\\w-]*)(\\b)

', null, 'general', 'regular expressions to find archaeological identifiers in a text for this project. A regular expression can have a named group "identifier" in which case only the group''s value will be used as identifier. If no named group is present the whole match will be used.', null, 1, '69051ddd-c82c-9747-b8ca-889a6cbdc030', '2023-05-02 20:03:30.000000', '2025-10-23 22:20:14.000000 +00:00', 'ADMIN', false, null, null, 39942485, '2025-10-23 15:20:14.000000', 63896822408133);
