INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('html_wc_popup', e'<!DOCTYPE html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta
      name="viewport"
      content="width=device-width, user-scalable=no, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0"
    />
    <meta http-equiv="X-UA-Compatible" content="ie=edge" />
    <title>Document</title>
    <style>
      * {
        margin: 0 0 0 0;
        border: none;
        padding: 0 0 0 0;
        font-family: Arial, sans-serif;
        font-size: 16px;
        user-select: none;
        -moz-user-select: none;
        -webkit-user-select: none;
        -ms-user-select: none;
      }

      body {
        height: 100%;
        width: 100%;
      }
      div {
        box-sizing: border-box;
      }
    </style>
    <style>
      .image-control {
        background-color: rgba(0, 0, 0, 0);
        overflow-x: scroll;
        overflow-y: hidden;
        white-space: nowrap;
        -ms-overflow-style: none;
        scrollbar-width: none;
      }
      .image-control::-webkit-scrollbar {
        display: none;
      }
      .image-control-button {
        display: inline-block;
        position: relative;
        background-color: white;
        width: 150px;
        height: 160px;
        margin-right: 2px;
        padding-top: 15px;
        border: 3px solid rgba(0, 0, 0, 0);
      }
      .image-control-button-img {
        margin-left: auto;
        margin-right: auto;
        width: 110px;
        height: 110px;
      }
      .image-control-button-text {
        margin-top: 5px;
        text-align: center;
      }

      /* grid stuff */
      .wc-grid {
        display: grid;
        padding: 1em;
        gap: 2px;
        grid-template-columns: minmax(auto, max-content) auto;
      }
      select {
        border: black solid 1pt;
      }
      .ct-col-header-1 {
        background-color: #154e73;
        color: white;
        font-weight: bold;
        padding: 2px 1em;
        text-align: center;
        padding: 2px 1em 2px 0px;
      }
      .wc-segment-title {
        padding: 4px 1em 4px 0px;

      }

      .left-align {
        text-align: left;
      }
      .ct-col-header-2 {
        padding: 0px 4px;
        text-align: right;
        background-color: #125d8c;
        color: white;
      }
      .ct-cell {
        /* background-color: #154e73; */
        padding: 4px;
        text-align: left;
        color: black;
      }
    </style>
  </head>
  <body>
    <div id="grid" class="wc-grid"></div>
  </body>
  <script>
    function newElement(classes, htmlInput) {
      let div = document.createElement("div");
      div.className = classes;
      div.innerHTML = htmlInput;
      return div;
    }

    function translateFMWCDefinition() {
      const lines = fmWCDefinition.split("\\n")
      const segments = []
      let segment = {}
      let titles = fmWCLabels.split("\\n")
      cSegment = 0
      codes = {}
      for (let l of lines) {
        l = l.trim()
        if (l === "*") {
          segment.title = titles[cSegment]
          segment.codes = codes
          segments.push(segment)
          segment = {}
          codes = {}
          cSegment++
        } else {
          code = l.split("=")
          if (code.length === 2) {
            codes[code[0].trim()] = code[1].trim()
          }
        }
      }
      return segments
    }

    // activate the following for FM:
    let fmWCLabels = `** wc_labels **`
    // activate the following for FM:
    let fmWCDefinition = `** wc_definition **`

    let wc_segments = translateFMWCDefinition()
    // replace the warecode with ** warecode ** in FileMaker
    let wc_warecode = "** warecode **"
    // replace the warecode with ** warecode ** end

    function wareCodeToSelect(el) {
      try {
      let row = parseInt(el.getAttribute("data-row"));
      wareCode = wc_warecode[row]
      el.value = wc_segments[row].codes[wareCode]??"?"
      } catch {
        el.value = "?"
      }
    }

    function setNthChar(str, index, newChar) {
      return str.padEnd(fmWCLabels.length,"?").slice(0, index) + newChar + str.slice(index + 1);
    }


    function selectToWareCode(el, event) {
      let row = parseInt(el.getAttribute("data-row"));
      let v = el.value
      let newCode = undefined
      if (v === "?") {
        newCode = "?"
      } else {
        codes = wc_segments[row].codes
        for (const code in codes) {
          if (codes[code] === v) {
            newCode = code
            break;
          }
        }
      }
      if (newCode) {
        wc_warecode = setNthChar(wc_warecode, row, newCode)
      }
      console.log(wc_warecode);
        if (typeof FileMaker !== \'undefined\') {
        FileMaker.PerformScript(
          "wc_pottery_set_warecode",
          wc_warecode
        );
      }
    }

    let grid = document.getElementById("grid");
    /* child = newElement("ct-col-header-1", "**task**");
    // child.style.backgroundColor = "white";
    grid.appendChild(child);
    child = newElement("ct-col-header-1", "**to do**");
    // child.style.backgroundColor = "white";
    grid.appendChild(child);
    child = newElement("ct-col-header-1", "**done**");
    // child.style.backgroundColor = "white";
    grid.appendChild(child); */

    let c = 0;
    for (const r of wc_segments) {
      grid.appendChild(newElement("wc-segment-title left-align", r.title));

      let select_html = `
            <select id=\\"wc-${c}\\" name=\\"wc-${c}\\" data-row=\\"${c}\\" data-reg-code=\\"${wc_warecode[c]}\\">
              `
      for (const wc in r.codes) {
        select_html += `<option>${r.codes[wc]}</option>`
      }
      select_html += `<option>?</option>`
      select_html += "</select>"
      grid.appendChild(
        newElement(
          "ct-cell", select_html
        ));
      c += 1;
    }

    let elements = document.getElementsByTagName("select");
    for (const e of elements) {
      if (e.id.startsWith("wc-")) {
        wareCodeToSelect(e)
      }
      e.addEventListener("change", (event) => {
        selectToWareCode(e, event)
      });
    }
  </script>
</html>', null, 'html', 'html template for the warecode pottery popup', null, 1, 'c393274a-bb67-9042-aabc-8f522bd32c49', '2025-11-26 11:44:38.000000', '2025-11-26 15:40:55.000000 +00:00', 'ADMIN', false, null, null, 96554373, '2025-11-26 16:40:55.000000', 63899790051628);
