INSERT INTO public.constants (id, value, value_ts, category, comment, field_type, sync, uid, created, modified, modified_by, repl_deleted, repl_tag, show_in_reduced_config, modified_tz, modified_ww, patch_index) VALUES ('warecode', e'1=coarse
2=medium
3=fine
*
1=Alluvial
2=Marl
3=other
*
1=scraped
2=rough - wet smoothed
3=well - dry smoothed
4=polished
*
0=no slip
1=white slip
2=red slip
3=other
*
1=normal
2=mostly chaft/straw
3=mostly sand
4=mostly limestone
5=none or few
6=fibres
*
', null, 'valuelists', 'A warecode consists of a group of single digits, each of which selects an entry from a group of values. You define a group by listing a code=value pair (the code must have one digit only!) per line. A group must end with a single line which has only a single * as the first and only value. For further instructions please see the configuration chapter in the manual.', null, 1, '2f12fb1b-22aa-e14d-bf3a-ad94e39fc082', '2018-06-20 18:46:14.000000', '2026-04-07 19:46:28.000000 +00:00', '', false, null, null, 40079121, '2026-04-07 15:46:28.000000', 63911187988850);
